-- Production verification: all fixtures, inventory, payment and ledger writes roll back.
begin;
do $$
declare admin_id uuid;founder uuid;customer uuid:=gen_random_uuid();linked uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();v1 uuid;v2 uuid;p1 uuid;p2 uuid;bank_id uuid;order_id uuid;full_id uuid;ship uuid;stage text;res jsonb;view jsonb;quote jsonb;t record;proof text;req numeric;user_ref text;
begin
 select company_id,founder_id into admin_id,founder from private.network_foundation where singleton;
 if admin_id is null or founder is null then raise exception 'Foundation unavailable';end if;
 select regexp_replace(member_code,'^MIO-','USR-') into user_ref from public.member_profiles where user_id=founder;
 insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,email_confirmed_at,created_at,updated_at)
 select id,'qa-vendor-order-'||id||'@example.invalid',jsonb_build_object('registration_type','customer','full_name','Rollback Order QA','phone','03000000000','country_code','PK','terms_accepted',true,'affiliate_code',case when id=linked then user_ref else null end,'shipping_address','Rollback QA address','shipping_city','Islamabad'),'{"provider":"email","providers":["email"]}',now(),now(),now() from (values(customer),(linked),(outsider)) x(id);
 if exists(select 1 from public.member_profiles where user_id in(customer,linked,outsider)) then raise exception 'Shopping signup created membership';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'aal','aal2','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',extract(epoch from now()))))::text,true);
 perform public.set_company_delivery(200,'Rollback vendor-order test');
 v1:=public.create_company_brand('Rollback QA vendor one','','');v2:=public.create_company_brand('Rollback QA vendor two','','');
 perform public.set_vendor_commission(v1,.30);perform public.set_vendor_commission(v2,.30);
 insert into public.products(vendor_id,name,description,category,price_pkr,stock_quantity,status) values(v1,'Rollback Product One','QA transaction only','QA',2000,100,'approved') returning id into p1;
 insert into public.products(vendor_id,name,description,category,price_pkr,stock_quantity,status) values(v2,'Rollback Product Two','QA transaction only','QA',2000,100,'approved') returning id into p2;
 bank_id:=public.admin_save_shopping_payment_account(null,'Rollback QA bank','Rollback QA account','QA-'||customer,'Temporary test account',true);
 perform set_config('request.jwt.claim.sub',customer::text,true);
 res:=public.place_shopping_order(jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',2),jsonb_build_object('product_id',p2,'quantity',2)),'Rollback QA','03000000000','Rollback QA address','Islamabad','qa-vendor-'||customer,'ADVANCE',null);order_id:=(res->>'order_id')::uuid;req:=(res->>'required_pkr')::numeric;
 view:=public.order_fulfillment_details(order_id);
 if jsonb_array_length(view->'shipments')<>2 or (view->>'delivery_fee_pkr')::numeric<>400 or (view->>'total_pkr')::numeric<>8400 or req<>840 then raise exception 'Per-vendor totals/funding incorrect';end if;
 if (view->'funding'->>'ready')::boolean then raise exception 'Unpaid order marked ready';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 begin perform public.advance_order_status(order_id,'confirmed');raise exception 'Unfunded order accepted';exception when others then if sqlerrm not like '%MIO hold%' then raise;end if;end;
 begin perform public.admin_confirm_order_payment(order_id);raise exception 'Early COD confirmed';exception when others then if sqlerrm not like '%only after delivery%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',customer::text,true);
 proof:=customer||'/'||order_id||'/qa-proof.png';insert into storage.objects(bucket_id,name,metadata) values('customer-payment-proofs',proof,'{"mimetype":"image/png","size":2048}');
 perform public.submit_order_payment(order_id,bank_id,'QA-ADVANCE-'||customer,proof,req);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.admin_review_shopping_advance(order_id,true,req,'Rollback verified partial advance');view:=public.order_fulfillment_details(order_id);
 if view->>'status'<>'placed' or not (view->'funding'->>'ready')::boolean or (view->'funding'->>'due_pkr')::numeric<>7560 then raise exception 'Advance confirmation/acceptance separation failed';end if;
 ship:=(view->'shipments'->0->>'id')::uuid;
 foreach stage in array array['confirmed','processing','shipped','delivered'] loop perform public.advance_vendor_shipment(ship,stage::public.order_status);end loop;
 view:=public.order_fulfillment_details(order_id);if view->>'status'<>'placed' then raise exception 'Parent advanced before other vendor';end if;
 begin perform public.cancel_unpaid_order(order_id);raise exception 'Dispatched order cancelled';exception when others then if sqlerrm not like '%already been dispatched%' then raise;end if;end;
 ship:=(view->'shipments'->1->>'id')::uuid;
 foreach stage in array array['confirmed','processing','shipped','delivered'] loop perform public.advance_vendor_shipment(ship,stage::public.order_status);end loop;
 if (select rewards_credited_at is not null from public.orders where id=order_id) then raise exception 'Unpaid rewards released';end if;
 perform public.admin_confirm_order_payment(order_id);view:=public.order_fulfillment_details(order_id);
 if view->>'payment_status'<>'confirmed' or view->>'status'<>'delivered' or (view->'funding'->>'due_pkr')::numeric<>0 then raise exception 'Delivered COD confirmation failed';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);execute 'set local role authenticated';
 if public.order_fulfillment_details(order_id) is not null then raise exception 'Invoice privacy failed';end if;
 begin perform public.admin_order_funding_states(array[order_id]);raise exception 'Admin controls leaked';exception when others then if sqlerrm not like '%Admin access%' then raise;end if;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',customer::text,true);
 res:=public.place_shopping_order(jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',1)),'Rollback QA','03000000000','Rollback QA address','Islamabad','qa-full-'||customer,'ADVANCE',null);full_id:=(res->>'order_id')::uuid;view:=public.order_fulfillment_details(full_id);
 proof:=customer||'/'||full_id||'/qa-full.png';insert into storage.objects(bucket_id,name,metadata) values('customer-payment-proofs',proof,'{"mimetype":"image/png","size":2048}');
 perform public.submit_order_payment(full_id,bank_id,'QA-FULL-'||customer,proof,(view->>'total_pkr')::numeric);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);perform public.admin_review_shopping_advance(full_id,true,(view->>'total_pkr')::numeric,'Rollback verified full payment');view:=public.order_fulfillment_details(full_id);
 if view->>'payment_status'<>'confirmed' or view->>'rewards_credited_at' is not null then raise exception 'Full upfront payment/reward timing failed';end if;
 perform set_config('request.jwt.claim.sub',linked::text,true);
 res:=public.place_shopping_order(jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',4)),'Rollback QA','03000000000','Rollback QA address','Islamabad','qa-hold-'||linked,'SPONSOR',null);view:=public.order_fulfillment_details((res->>'order_id')::uuid);
 if (view->'funding'->>'paid_pkr')::numeric<>0 or (view->'funding'->>'due_pkr')::numeric<>(view->>'total_pkr')::numeric or view->'funding'->>'method'<>'Sponsor hold' then raise exception 'Sponsor hold treated as payment';end if;
 select * into t from private.marketplace_bundle_types where name='Bundle 3' and status='enabled';if t.id is null then raise exception 'Bundle 3 unavailable';end if;
 perform set_config('request.jwt.claim.sub',customer::text,true);
 quote:=public.quote_marketplace_bundle(t.id,v1,jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',t.required_units-1),jsonb_build_object('product_id',p2,'quantity',1)));
 if (quote->>'vendor_count')::integer<>2 or (quote->>'ppv')::numeric<>floor((quote->>'original_ppv')::numeric/t.ppv_divider*10000)/10000 then raise exception 'Bundle vendor/PPV mismatch';end if;
 res:=public.place_configured_bundle_order(t.id,v1,jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',t.required_units-1),jsonb_build_object('product_id',p2,'quantity',1)),quote->>'quote_key',jsonb_build_object('p_items',jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',1)),'p_shipping_name','Rollback QA','p_shipping_phone','03000000000','p_shipping_address','Rollback QA address','p_shipping_city','Islamabad','p_idempotency_key','qa-bundle-'||customer,'p_funding_method','ADVANCE'));
 view:=public.order_fulfillment_details((res->>'order_id')::uuid);if jsonb_array_length(view->'shipments')<>2 or (view->>'delivery_fee_pkr')::numeric<>400 then raise exception 'Bundle plus normal product duplicated vendor delivery';end if;
 perform set_config('mio.qa_vendor_order_result',jsonb_build_object('direct_and_affiliate_signup','pass','per_vendor_delivery_and_invoices','pass','funding_and_stage_guards','pass','payment_evidence_approval','pass','independent_vendor_fulfillment','pass','delivery_before_cod_confirmation','pass','full_prepayment_and_reward_timing','pass','sponsor_hold_not_payment','pass','multi_vendor_bundle_economics','pass','authenticated_invoice_privacy','pass','test_data','rolled back')::text,true);
end $$;
select current_setting('mio.qa_vendor_order_result')::jsonb as result;
rollback;
